const items = $input.all();
const output = [];

for (const item of items) {
  const leads = item.json.leads || {};
  const messages = item.json.messages || {};
  const config = item.json.config || { leadCount: 200, seed: null, enrichmentMode: 'offline', dryRun: true, pipelineRunId: null };

  let nextAction = null;
  let endpoint = null;
  let params = {};

  // Check if this is a full pipeline run request (config-driven)
  // If pipelineRunId is provided, ALWAYS run full pipeline (it will clear tables internally)
  if (config.pipelineRunId) {
    // This is a fresh pipeline run - call run_pipeline endpoint which handles everything
    nextAction = 'run_pipeline';
    endpoint = 'http://localhost:8001/tools/run_pipeline';
    params = {
      leadCount: config.leadCount,
      seed: config.seed,
      enrichmentMode: config.enrichmentMode,
      dryRun: config.dryRun,
      pipelineRunId: config.pipelineRunId
    };
  }
  // Agent decision logic for incremental processing
  else if (messages.APPROVED && messages.APPROVED > 0) {
    nextAction = 'send_messages';
    endpoint = 'http://localhost:8001/tools/send_messages';
    params = { use_queue: true, batch_size: 50, dry_run: config.dryRun };
  }
  else if (messages.PENDING && messages.PENDING > 0) {
    nextAction = 'review_messages';
    endpoint = 'http://localhost:8001/tools/review_messages';
    params = {};
  }
  else if (leads.ENRICHED && leads.ENRICHED > 0) {
    nextAction = 'generate_messages';
    endpoint = 'http://localhost:8001/tools/generate_messages';
    params = { limit: 50, min_confidence_score: 60 };
  }
  else if (leads.NEW && leads.NEW > 0) {
    nextAction = 'enrich_leads';
    endpoint = 'http://localhost:8001/tools/enrich_leads';
    params = { mode: config.enrichmentMode, limit: 50 };
  }
  else if ((!leads.NEW || leads.NEW < 10) && (!leads.ENRICHED || leads.ENRICHED < 20)) {
    nextAction = 'generate_leads';
    endpoint = 'http://localhost:8001/tools/generate_leads';
    params = { count: config.leadCount, save_to_db: true };
    if (config.seed) {
      params.seed = config.seed;
    }
  }
  else {
    nextAction = 'wait';
    endpoint = null;
  }

  output.push({
    json: {
      ...item.json,
      agent_decision: {
        action: nextAction,
        endpoint: endpoint,
        params: params,
        timestamp: new Date().toISOString()
      }
    }
  });
}

return output;

// Merge webhook config with stats from Get Pipeline Stats node
// The webhook config was saved by previous node, stats come from HTTP request

// Get stats from the Get Pipeline Stats node
const statsData = $input.first().json;

// Get webhook config from the Webhook Trigger node (if available)
let webhookConfig = { 
  leadCount: 200, 
  seed: null, 
  enrichmentMode: 'offline', 
  dryRun: true,
  pipelineRunId: `run_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
};

// Try to access webhook data from the execution
try {
  const webhookItems = $('Webhook Trigger').all();
  if (webhookItems && webhookItems.length > 0) {
    const webhookData = webhookItems[0].json;
    console.log('Webhook data from trigger:', JSON.stringify(webhookData, null, 2));

    // n8n webhook node puts POST body at root level
    if (webhookData.config) {
      console.log('Found config at root level');
      webhookConfig = webhookData.config;
    } else if (webhookData.body && webhookData.body.config) {
      console.log('Found config in body');
      webhookConfig = webhookData.body.config;
    }
  }
} catch (e) {
  console.log('No webhook data, using defaults for scheduled run');
}

console.log('Final config:', JSON.stringify(webhookConfig, null, 2));

return [{
  json: {
    ...statsData,
    config: webhookConfig
  }
}];

